using backend.Domain.Entities;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace backend.Persistence.Configurations;

public class LessonCategoryConfiguration : IEntityTypeConfiguration<LessonCategory>
{
    public void Configure(EntityTypeBuilder<LessonCategory> builder)
    {
        builder.HasKey(c => c.Id);
        builder.Property(c => c.Name         ).IsRequired().HasMaxLength(50);
        builder.Property(c => c.TitleEn      ).HasMaxLength(150);
        builder.Property(c => c.TitleBn      ).HasMaxLength(150);
        builder.Property(c => c.DescriptionEn).HasMaxLength(500);
        builder.Property(c => c.DescriptionBn).HasMaxLength(500);
        builder.ToTable("LessonCategories");

        builder.HasData(
            new LessonCategory { Id = 1, Name = "Arabic Letters", TitleEn = "Arabic Alphabet",      TitleBn = "আরবি বর্ণমালা",  DescriptionEn = "Arabic has 28 letters. Each letter changes shape based on its position in a word.", DescriptionBn = "আরবিতে ২৮টি বর্ণ আছে। শব্দের মধ্যে অবস্থানের উপর ভিত্তি করে প্রতিটি বর্ণের আকার পরিবর্তন হয়।" },
            new LessonCategory { Id = 2, Name = "Harakat",        TitleEn = "What is Harakat?",     TitleBn = "হরকত কী?",       DescriptionEn = "Harakat are short vowel marks that determine how a letter is pronounced.",         DescriptionBn = "হরকত হলো ছোট স্বরচিহ্ন যা নির্ধারণ করে কীভাবে একটি বর্ণ উচ্চারণ করতে হবে।" },
            new LessonCategory { Id = 3, Name = "Tanween",        TitleEn = "What is Tanween?",     TitleBn = "তানউইন কী?",     DescriptionEn = "Tanween is a \'n\' sound added at the end of a word.",                          DescriptionBn = "তানউইন হলো শব্দের শেষে একটি \'ন\' শব্দ যোগ করা।" },
            new LessonCategory { Id = 4, Name = "Sukoon",         TitleEn = "What is Sukoon?",      TitleBn = "সুকুন কী?",      DescriptionEn = "Sukoon means a letter has no vowel. It appears as a small circle above the letter.", DescriptionBn = "সুকুন মানে একটি বর্ণের কোনো স্বর নেই। এটি বর্ণের উপরে একটি ছোট বৃত্ত হিসেবে দেখা যায়।" },
            new LessonCategory { Id = 5, Name = "Shaddah",        TitleEn = "What is Shaddah?",     TitleBn = "শাদ্দা কী?",     DescriptionEn = "Shaddah means the consonant is doubled in pronunciation.",                         DescriptionBn = "শাদ্দা মানে বর্ণটি উচ্চারণে দ্বিগুণ হয়।" },
            new LessonCategory { Id = 6, Name = "Word Building",  TitleEn = "Word Building",        TitleBn = "শব্দ গঠন",       DescriptionEn = "Learn to read and pronounce common Arabic words used in daily prayers.",           DescriptionBn = "দৈনন্দিন নামাযে ব্যবহৃত সাধারণ আরবি শব্দ পড়তে ও উচ্চারণ করতে শিখুন।" }
        );
    }
}

