        builder.Property(i => i.ArabicText   ).IsRequired().HasMaxLength(20);
        builder.Property(i => i.SoundText    ).HasMaxLength(30);
        builder.Property(i => i.AudioUrl     ).HasMaxLength(300);
        builder.Property(i => i.DescriptionEn).HasMaxLength(300);
        builder.Property(i => i.DescriptionBn).HasMaxLength(300);
        builder.HasIndex(i => new { i.CategoryId, i.OrderNo }).IsUnique();
        builder.HasOne(i => i.Category)
